-- CRM Advanced: tags, custom fields, saved views, imports, dedupe, automation and reports.
create table if not exists public.crm_tags(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,color text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(organization_id,name));
create table if not exists public.crm_entity_tags(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),tag_id uuid not null references public.crm_tags(id) on delete cascade,entity_type text not null,entity_id uuid not null,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(tag_id,entity_type,entity_id));
create table if not exists public.crm_custom_fields(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),entity_type text not null,field_key text not null,field_label text not null,field_type text not null default 'text',options jsonb not null default '[]',required boolean not null default false,position int not null default 0,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(organization_id,entity_type,field_key));
create table if not exists public.crm_custom_field_values(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),field_id uuid not null references public.crm_custom_fields(id) on delete cascade,entity_type text not null,entity_id uuid not null,value jsonb,updated_by uuid references public.profiles(id),updated_at timestamptz not null default now(),unique(field_id,entity_type,entity_id));
create table if not exists public.crm_saved_views(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),entity_type text not null,name text not null,filters jsonb not null default '{}',columns jsonb not null default '[]',sort jsonb not null default '[]',shared boolean not null default false,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,entity_type,name));
create table if not exists public.crm_import_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),entity_type text not null,source_format text not null,filename text,mapping jsonb not null default '{}',status text not null default 'queued',total_rows int not null default 0,imported_rows int not null default 0,skipped_rows int not null default 0,error_rows jsonb not null default '[]',created_by uuid references public.profiles(id),created_at timestamptz not null default now(),finished_at timestamptz);
create table if not exists public.crm_dedupe_clusters(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),entity_type text not null,master_id uuid not null,candidate_ids uuid[] not null,match_reason jsonb not null default '{}',status text not null default 'open',snapshot jsonb not null default '{}',resolved_by uuid references public.profiles(id),resolved_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.crm_automation_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,entity_type text not null,enabled boolean not null default true,trigger_event text not null,conditions jsonb not null default '{}',actions jsonb not null default '[]',created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.crm_automation_runs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),rule_id uuid not null references public.crm_automation_rules(id) on delete cascade,event_key text not null,event_payload jsonb not null default '{}',status text not null default 'queued',result jsonb not null default '{}',error text,started_at timestamptz,finished_at timestamptz,created_at timestamptz not null default now(),unique(rule_id,event_key));
create index if not exists crm_entity_tags_entity_idx on public.crm_entity_tags(organization_id,entity_type,entity_id);
create index if not exists crm_custom_fields_entity_idx on public.crm_custom_fields(organization_id,entity_type,position);
create index if not exists crm_custom_values_entity_idx on public.crm_custom_field_values(organization_id,entity_type,entity_id);
create index if not exists crm_saved_views_org_entity_idx on public.crm_saved_views(organization_id,entity_type);
create index if not exists crm_import_jobs_org_status_idx on public.crm_import_jobs(organization_id,status,created_at desc);
create index if not exists crm_dedupe_org_status_idx on public.crm_dedupe_clusters(organization_id,status,entity_type);
create index if not exists crm_automation_runs_org_status_idx on public.crm_automation_runs(organization_id,status,created_at desc);
do $$ declare t text;begin for t in select unnest(array['crm_tags','crm_entity_tags','crm_custom_fields','crm_custom_field_values','crm_saved_views','crm_import_jobs','crm_dedupe_clusters','crm_automation_rules','crm_automation_runs']) loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists crm_org_select on public.%I',t); execute format('drop policy if exists crm_org_write on public.%I',t); execute format('drop policy if exists crm_org_delete on public.%I',t); execute format('create policy crm_org_select on public.%I for select to authenticated using ((select public.crm_org_accessible(organization_id)) and (select public.user_role()) <> ''client''::user_role)',t); execute format('create policy crm_org_write on public.%I for all to authenticated using (organization_id=(select public.user_org_id()) and (select public.user_role()) in (''owner''::user_role,''admin''::user_role,''broker''::user_role)) with check (organization_id=(select public.user_org_id()) and (select public.user_role()) in (''owner''::user_role,''admin''::user_role,''broker''::user_role))',t); execute format('create policy crm_org_delete on public.%I for delete to authenticated using (organization_id=(select public.user_org_id()) and (select public.user_role()) in (''owner''::user_role,''admin''::user_role))',t); end loop;end $$;
create or replace function public.crm_sales_funnel(p_organization_id uuid default public.user_org_id()) returns jsonb language sql stable security invoker set search_path=public,pg_catalog as $$select coalesce(jsonb_agg(to_jsonb(x) order by x.position),'[]'::jsonb) from(select s.id,s.name,s.position,count(d.id)::int deal_count,coalesce(sum(d.amount),0)::numeric total_amount,coalesce(avg(d.amount),0)::numeric avg_amount from crm_pipeline_stages s left join crm_deals d on d.stage_id=s.id and d.deleted_at is null join crm_pipelines p on p.id=s.pipeline_id and p.organization_id=p_organization_id and p.deleted_at is null where s.deleted_at is null group by s.id,s.name,s.position)x$$;
create or replace function public.crm_win_rate(p_organization_id uuid default public.user_org_id()) returns jsonb language sql stable security invoker set search_path=public,pg_catalog as $$select jsonb_build_object('won',count(*) filter(where lower(coalesce(s.name,'')) like '%won%' or lower(coalesce(s.name,'')) like '%closed%'),'total',count(*),'rate',case when count(*)=0 then 0 else round(100.0*count(*) filter(where lower(coalesce(s.name,'')) like '%won%' or lower(coalesce(s.name,'')) like '%closed%')/count(*),2) end) from crm_deals d left join crm_pipeline_stages s on s.id=d.stage_id where d.organization_id=p_organization_id and d.deleted_at is null$$;
create or replace function public.crm_deal_age(p_organization_id uuid default public.user_org_id()) returns jsonb language sql stable security invoker set search_path=public,pg_catalog as $$select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from(select d.id,d.title,d.amount,extract(day from now()-d.created_at)::int age_days from crm_deals d where d.organization_id=p_organization_id and d.deleted_at is null order by d.created_at)x$$;
create or replace function public.crm_user_performance(p_organization_id uuid default public.user_org_id()) returns jsonb language sql stable security invoker set search_path=public,pg_catalog as $$select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) from(select d.owner_id,count(*)::int deals,coalesce(sum(d.amount),0)::numeric pipeline_value,count(*) filter(where lower(coalesce(s.name,'')) like '%won%' or lower(coalesce(s.name,'')) like '%closed%')::int won from crm_deals d left join crm_pipeline_stages s on s.id=d.stage_id where d.organization_id=p_organization_id and d.deleted_at is null group by d.owner_id)x$$;
create or replace function public.crm_monthly_forecast(p_organization_id uuid default public.user_org_id()) returns jsonb language sql stable security invoker set search_path=public,pg_catalog as $$with months as(select date_trunc('month',now())+make_interval(months=>g) month_start from generate_series(0,5) g),hist as(select date_trunc('month',d.created_at)m,sum(coalesce(d.amount,0))amount from crm_deals d where d.organization_id=p_organization_id and d.deleted_at is null group by 1),base as(select coalesce(avg(amount),0)avg_amount from hist where m>=date_trunc('month',now())-interval '3 months')select coalesce(jsonb_agg(jsonb_build_object('month_gregorian',m.month_start,'forecast_amount',round((select avg_amount from base),2)) order by m.month_start),'[]'::jsonb)from months m$$;
revoke all on function public.crm_sales_funnel(uuid),public.crm_win_rate(uuid),public.crm_deal_age(uuid),public.crm_user_performance(uuid),public.crm_monthly_forecast(uuid) from public,anon;
grant execute on function public.crm_sales_funnel(uuid),public.crm_win_rate(uuid),public.crm_deal_age(uuid),public.crm_user_performance(uuid),public.crm_monthly_forecast(uuid) to authenticated;
